    /// Search suggestions for a keyword; `entries` truncated to `limit`
    /// when limit > 0.
    pub async fn suggest_keywords(&self, keyword: &str, limit: usize) -> Value {
        let plan = match build_suggest_request(keyword, None, 0, None) {
            Ok(p) => p,
            Err(e) => return error_value("invalid_request", e.to_string()),
        };
        let mut result = self.execute_live(&plan).await;
        if limit > 0 && result.get("ok").and_then(|v| v.as_bool()) == Some(true) {
            if let Some(entries) = result
                .get_mut("data")
                .and_then(|d| d.get_mut("entries"))
                .and_then(|e| e.as_array_mut())
            {
                entries.truncate(limit);
            }
        }
        result
    }

