fn env_first(names: &[&str]) -> Option<String> {
    for name in names {
        if let Ok(value) = std::env::var(name) {
            if !value.is_empty() {
                return Some(value);
            }
        }
    }
    None
}

// ---------------------------------------------------------------------------
// Runtime resolution (zero-config by default)
//
// The user configures nothing. The two runtime pieces resolve as
// follows.
//
// Identity — an explicit override wins:
//   1. $GOOFISH_IDENTITY / $SHOPPING_MCP_GOOFISH_IDENTITY (path to a
//      JSON file {"utdid": ..., "device_id": ..., "ttid": ...})
//   2. the server-owned identity in the data directory
//      ($XDG_DATA_HOME/zero-search-mcp/goofish/identity.json,
//      default ~/.local/share/zero-search-mcp/...) — generated by
//      the server itself on first use with the app's own UTDID
//      algorithm (see the `identity` module) and reused after that
//   3. the `identity` key of a goofish.json config file
//   4. a bundle `identity.json`
// Steps 3–4 only matter for pre-ZeroSearch deployments; step 2 makes
// them unreachable in a fresh install.
//
// Signing serve command:
//   1. $GOOFISH_SG_SERVE / $SHOPPING_MCP_GOOFISH_SG_SERVE
//   2. the `sg_serve` key of the config file
//   3. an auto-discovered runtime *bundle*: a `goofish-runtime/`
//      directory next to the server executable (or the executable's
//      own directory) holding `serve.sh` (or `serve_lowmem.sh`), the
//      same directory under the server's data directory, or the
//      legacy `$HOME/.shopping-mcp/goofish-runtime/`.
//   4. when none of those resolve but the distribution shipped a
//      `goofish-payload/` next to the executable, the bundle under
//      the data directory is assembled on first use (the app
//      package is downloaded and verified by the server itself;
//      see the `provision` module) and step 3 then finds it.
// The bundle is part of the deployment, not a user setting: the MCP
// host configuration stays just the binary path. When no serve
// command resolves at all, live calls refuse with missing_runtime
// (or provisioning_failed when step 4 was attempted and failed)
// and send nothing.
//
// Config file (overrides only):
//   { "sg_serve": "/path/to/serve.sh", "identity": "/path/to/identity.json" }
// Lookup order for the file itself: $SHOPPING_MCP_GOOFISH_CONFIG
// (that file only, when set), then goofish.json next to the server
// executable, then $XDG_CONFIG_HOME/shopping-mcp/goofish.json
// (default ~/.config/shopping-mcp/goofish.json). Relative paths
// inside the file resolve against its directory (for `sg_serve`,
// only when the value is a single token; a command with arguments
// is used verbatim).
// ---------------------------------------------------------------------------

/// Parsed `goofish.json` runtime config file.
#[derive(Debug, Default, PartialEq)]
struct FileConfig {
    sg_serve: Option<String>,
    identity: Option<String>,
}

fn parse_file_config(text: &str, base_dir: &Path) -> Option<FileConfig> {
    let doc: Value = serde_json::from_str(text).ok()?;
    let obj = doc.as_object()?;
    let pick = |keys: &[&str]| -> Option<String> {
        keys.iter()
            .filter_map(|k| obj.get(*k))
            .filter_map(crate::util::as_str)
            .map(|s| s.trim().to_string())
            .find(|s| !s.is_empty())
    };
    let resolve_path = |value: String| -> String {
        let path = Path::new(&value);
        if path.is_relative() {
            base_dir.join(path).to_string_lossy().into_owned()
        } else {
            value
        }
    };
    let identity = pick(&["identity", "identity_file", "goofish_identity"]).map(resolve_path);
    // A serve *command* may carry arguments; only a bare single-token
    // path is resolved against the config file's directory.
    let sg_serve = pick(&["sg_serve", "serve", "goofish_sg_serve"]).map(|value| {
        if value.contains(char::is_whitespace) {
            value
        } else {
            resolve_path(value)
        }
    });
    Some(FileConfig { sg_serve, identity })
}

fn config_file_candidates() -> Vec<PathBuf> {
    let mut out = Vec::new();
    if let Ok(exe) = std::env::current_exe() {
        if let Some(dir) = exe.parent() {
            out.push(dir.join("goofish.json"));
        }
    }
    let config_home = std::env::var("XDG_CONFIG_HOME")
        .ok()
        .filter(|s| !s.is_empty())
        .map(PathBuf::from)
        .or_else(|| {
            std::env::var("HOME")
                .ok()
                .filter(|s| !s.is_empty())
                .map(|home| PathBuf::from(home).join(".config"))
        });
    if let Some(dir) = config_home {
        out.push(dir.join("shopping-mcp").join("goofish.json"));
    }
    out
}

fn load_file_config() -> Option<FileConfig> {
    if let Some(explicit) = env_first(&CONFIG_ENVS) {
        // An explicit config path is authoritative: default locations
        // are not searched as well.
        let path = PathBuf::from(&explicit);
        let text = std::fs::read_to_string(&path).ok()?;
        let base = path.parent().map(|p| p.to_path_buf()).unwrap_or_default();
        return parse_file_config(&text, &base);
    }
    for path in config_file_candidates() {
        if let Ok(text) = std::fs::read_to_string(&path) {
            let base = path.parent().map(|p| p.to_path_buf()).unwrap_or_default();
            if let Some(config) = parse_file_config(&text, &base) {
                return Some(config);
            }
        }
    }
    None
}

/// The resolved live runtime: overrides first (environment, then
/// the config file), then the zero-config defaults — the
/// server-generated identity and the auto-discovered bundle.
struct RuntimeSettings {
    identity_path: Option<String>,
    serve_command: Option<String>,
}

/// Serve script names a bundle may carry, in preference order.
/// Provisioning generates `serve.cmd` on Windows and `serve.sh`
/// elsewhere; the shell names stay valid on every platform so
/// hand-assembled bundles keep working.
#[cfg(windows)]
const SERVE_CANDIDATES: [&str; 3] = ["serve.cmd", "serve.sh", "serve_lowmem.sh"];
#[cfg(not(windows))]
const SERVE_CANDIDATES: [&str; 2] = ["serve.sh", "serve_lowmem.sh"];

/// Runtime pieces found in one bundle directory: a serve script
/// (`serve.sh`, falling back to `serve_lowmem.sh`) and/or an
/// `identity.json`. Either piece may be absent.
fn bundle_in(dir: &Path) -> FileConfig {
    let serve = SERVE_CANDIDATES
        .iter()
        .map(|name| dir.join(name))
        .find(|path| path.is_file());
    let identity_path = dir.join("identity.json");
    FileConfig {
        sg_serve: serve.map(|path| path.to_string_lossy().into_owned()),
        identity: if identity_path.is_file() {
            Some(identity_path.to_string_lossy().into_owned())
        } else {
            None
        },
    }
}

fn discover_bundle() -> FileConfig {
    let mut dirs: Vec<PathBuf> = Vec::new();
    if let Ok(exe) = std::env::current_exe() {
        if let Some(dir) = exe.parent() {
            dirs.push(dir.join("goofish-runtime"));
            dirs.push(dir.to_path_buf());
        }
    }
    if let Some(data) = identity::data_dir() {
        dirs.push(data.join("goofish-runtime"));
    }
    if let Some(home) = std::env::var("HOME").ok().filter(|s| !s.is_empty()) {
        dirs.push(
            PathBuf::from(home)
                .join(".shopping-mcp")
                .join("goofish-runtime"),
        );
    }
    let mut found = FileConfig::default();
    for dir in dirs {
        let bundle = bundle_in(&dir);
        if found.sg_serve.is_none() {
            found.sg_serve = bundle.sg_serve;
        }
        if found.identity.is_none() {
            found.identity = bundle.identity;
        }
        if found.sg_serve.is_some() && found.identity.is_some() {
            break;
        }
    }
    found
}

fn resolve_runtime() -> RuntimeSettings {
    let file = load_file_config().unwrap_or_default();
    let bundle = discover_bundle();
    RuntimeSettings {
        // The server-owned identity (auto-generated on first use)
        // outranks file/bundle identities so a fresh install always
        // lands on the managed document; explicit environment
        // overrides still win.
        identity_path: env_first(&IDENTITY_ENVS)
            .or_else(identity::load_or_create_identity)
            .or(file.identity)
            .or(bundle.identity),
        serve_command: env_first(&SERVE_ENVS).or(file.sg_serve).or(bundle.sg_serve),
    }
}

/// The most recent first-use provisioning failure, if any. Kept
/// so a live call can report `provisioning_failed` (the assembly
/// error) instead of the generic `missing_runtime`.
static PROVISION_ERROR: Mutex<Option<String>> = Mutex::new(None);

/// `resolve_runtime`, plus first-use provisioning: when no serve
/// command resolves but the distribution shipped a
/// `goofish-payload/` next to the executable, assemble the runtime
/// in the data directory (see the `provision` module) and resolve
/// again. Synchronous and potentially slow (a ~269 MB download on
/// the very first use); async callers run it on a blocking thread.
fn resolve_runtime_with_provision() -> RuntimeSettings {
    let runtime = resolve_runtime();
    if runtime.serve_command.is_some() || !provision::payload_available() {
        return runtime;
    }
    match provision::ensure_provisioned() {
        Ok(_) => resolve_runtime(),
        Err(e) => {
            *PROVISION_ERROR.lock().unwrap() = Some(e);
            resolve_runtime()
        }
    }
}

/// True when the signing serve command resolves — or can be made
/// to resolve by first-use provisioning from a shipped payload
/// (the identity is server-generated on demand, so it is never
/// the missing piece). Used by the server to decide whether the
/// background pre-warm (which performs any provisioning and then
/// boots the harness) is worth starting, and by the e2e test to
/// pick its expectation.
pub fn runtime_configured() -> bool {
    resolve_runtime().serve_command.is_some() || provision::payload_available()
}

/// Split a serve command into program + arguments, honouring single
/// and double quotes and backslash escapes (shell-like tokenisation;
/// no variable or glob expansion). An empty/blank command yields an
/// empty vector.
fn split_serve_command(command: &str) -> Vec<String> {
    let mut parts = Vec::new();
    let mut current = String::new();
    let mut has_current = false;
    let mut quote: Option<char> = None;
    let mut chars = command.chars();
    while let Some(c) = chars.next() {
        match quote {
            Some(q) => {
                if c == q {
                    quote = None;
                } else if c == '\\' && q == '"' {
                    match chars.next() {
                        Some(esc @ ('"' | '\\')) => current.push(esc),
                        Some(other) => {
                            current.push('\\');
                            current.push(other);
                        }
                        None => current.push('\\'),
                    }
                } else {
                    current.push(c);
                }
            }
            None => match c {
                '\'' | '"' => {
                    quote = Some(c);
                    has_current = true;
                }
                '\\' => {
                    has_current = true;
                    match chars.next() {
                        Some(esc) => current.push(esc),
                        None => current.push('\\'),
                    }
                }
                c if c.is_whitespace() => {
                    if has_current {
                        parts.push(std::mem::take(&mut current));
                        has_current = false;
                    }
                }
                _ => {
                    has_current = true;
                    current.push(c);
                }
            },
        }
    }
    if has_current {
        parts.push(current);
    }
    parts
}

/// Extract a numeric item id from a bare id or a fleamarket/goofish URL.
pub fn extract_item_id(product: &str) -> Option<String> {
    let trimmed = product.trim();
    if !trimmed.is_empty() && trimmed.chars().all(|c| c.is_ascii_digit()) {
        return Some(trimmed.to_string());
    }
    let by_param = regex::Regex::new(r"[?&]id=(\d+)").ok()?;
    if let Some(cap) = by_param.captures(trimmed) {
        return Some(cap[1].to_string());
    }
    let re = regex::Regex::new(r"\d{4,}").ok()?;
    re.find(trimmed).map(|m| m.as_str().to_string())
}

/// application/x-www-form-urlencoded encoding (quote_plus semantics:
/// unreserved bytes kept, space -> '+', everything else %XX).
fn percent_encode(value: &str) -> String {
    let mut out = String::with_capacity(value.len());
    for byte in value.bytes() {
        match byte {
            b'A'..=b'Z' | b'a'..=b'z' | b'0'..=b'9' | b'-' | b'_' | b'.' | b'~' => {
                out.push(byte as char)
            }
            b' ' => out.push('+'),
            _ => out.push_str(&format!("%{byte:02X}")),
        }
    }
    out
}

