    #[test]
    fn classification_and_halt() {
        let envelope = json!({
            "api": "mtop.taobao.idlemtopsearch.search.suggest",
            "v": "4.0",
            "ret": ["FAIL_SYS_USER_VALIDATE::哎哟喂,被挤爆啦,请稍后重试"],
            "data": {},
        });
        let core = CoreClient::new(StatusMockTransport::new(vec![
            (419, envelope.clone()),
            (419, envelope),
        ]));
        let plan = build_suggest_request("iphone", None, 0, None).unwrap();
        let result = core.execute(&plan);
        assert_eq!(result["ok"], json!(false));
        assert_eq!(result["error"]["category"], json!("verification_required"));
        assert_eq!(result["error"]["status"], json!(419));
        assert_eq!(core.halted_by().as_deref(), Some("verification_required"));
        // Halted: no further transport use.
        let result = core.execute(&plan);
        assert_eq!(result["error"]["category"], json!("send_halted"));
        assert_eq!(core.transport.requests.lock().unwrap().len(), 1);
        // After reset, sends flow again (and re-trip the halt).
        core.reset_send_halt();
        let result = core.execute(&plan);
        assert_eq!(result["error"]["category"], json!("verification_required"));
        assert_eq!(core.transport.requests.lock().unwrap().len(), 2);
    }

