    // The env lock must be held across the call: it serializes the
    // process-wide environment mutation this test performs.
    #[allow(clippy::await_holding_lock)]
    #[tokio::test]
    async fn missing_runtime_refused_before_any_send() {
        let _guard = crate::identity::ENV_TEST_LOCK.lock().unwrap();
        for name in IDENTITY_ENVS.iter().chain(SERVE_ENVS.iter()) {
            std::env::remove_var(name);
        }
        // Pin the config lookup to a nonexistent file so a config
        // installed on the developer machine cannot turn this
        // refusal test into a live send.
        std::env::set_var(
            "SHOPPING_MCP_GOOFISH_CONFIG",
            "/nonexistent/shopping-mcp/goofish.json",
        );
        // Same for bundle auto-discovery under $HOME.
        std::env::set_var("HOME", "/nonexistent");
        std::env::set_var("XDG_CONFIG_HOME", "/nonexistent");
        // Isolate the server data directory: the identity is
        // auto-generated there, so identity must NOT be the missing
        // piece — only the signer serve command is.
        let data_home = std::env::temp_dir().join(format!(
            "zero-search-goofish-missing-{}",
            std::process::id()
        ));
        std::env::set_var("XDG_DATA_HOME", &data_home);
        let client = GoofishClient::new();
        let result = client
            .search_products("示例", 1, 10, None, None, None)
            .await;
        assert_eq!(result["provider"], json!("goofish"));
        assert_eq!(result["ok"], json!(false));
        assert_eq!(result["error"]["category"], json!("missing_runtime"));
        let message = result["error"]["message"].as_str().unwrap();
        assert!(message.contains("signer serve command"), "{message}");
        // The identity was generated into the isolated data dir as
        // part of the same resolution (and the call still refused
        // before any send because the signer harness is absent).
        let identity_file = data_home
            .join("zero-search-mcp")
            .join("goofish")
            .join("identity.json");
        assert!(
            identity_file.is_file(),
            "auto identity missing at {identity_file:?}"
        );
        std::env::remove_var("XDG_DATA_HOME");
        std::fs::remove_dir_all(&data_home).ok();
    }

